  [last_check] DATETIME2(0) NOT NULL CONSTRAINT [DF_hlr_template_last_check] DEFAULT (SYSUTCDATETIME()),
  [is_deleted] TINYINT NOT NULL CONSTRAINT [DF_hlr_template_is_deleted] DEFAULT (0),
  CONSTRAINT [PK_hlr_template] PRIMARY KEY ([msisdn])
);
CREATE INDEX [idx_last_check] ON [hlr_template] ([last_check]);
CREATE INDEX [idx_network] ON [hlr_template] ([mcc], [mnc]);
